242→#[cfg(test)]
243→mod tests {
244→    use super::*;
245→
246→    fn make_prompt(key: &str, prompt_type: PromptType, default: Option<&str>) -> Prompt {
247→        Prompt {
248→            key: key.to_string(),
249→            question: "Test question?".to_string(),
250→            prompt_type,
251→            default: default.map(String::from),
252→        }
253→    }
254→
255→    #[test]
256→    fn prompt_creation() {
257→        let prompt = make_prompt("test", PromptType::Input, Some("default"));
258→        assert_eq!(prompt.key, "test");
259→        assert_eq!(prompt.default, Some("default".to_string()));
260→    }
261→
262→    #[test]
263→    fn prompt_type_confirm_creation() {
264→        let prompt = make_prompt("confirm", PromptType::Confirm, None);
265→        assert!(matches!(prompt.prompt_type, PromptType::Confirm));
266→    }
267→
268→    #[test]
269→    fn prompt_type_select_with_options() {
270→        let options = vec![
271→            PromptOption {
272→                label: "Option A".to_string(),
273→                value: "a".to_string(),
274→            },
275→            PromptOption {
276→                label: "Option B".to_string(),
277→                value: "b".to_string(),
278→            },
279→        ];
280→        let prompt = make_prompt(
281→            "select",
282→            PromptType::Select {
283→                options: options.clone(),
284→            },
285→            None,
286→        );
287→        if let PromptType::Select { options: stored } = prompt.prompt_type {
288→            assert_eq!(stored.len(), 2);
289→            assert_eq!(stored[0].value, "a");
290→        } else {
291→            panic!("Expected Select variant");
292→        }
293→    }
294→
295→    #[test]
296→    fn prompt_type_multiselect_with_options() {
297→        let options = vec![PromptOption {
298→            label: "Feature 1".to_string(),
299→            value: "f1".to_string(),
300→        }];
301→        let prompt = make_prompt(
302→            "multi",
303→            PromptType::MultiSelect {
304→                options: options.clone(),
305→            },
306→            None,
307→        );
308→        if let PromptType::MultiSelect { options: stored } = prompt.prompt_type {
309→            assert_eq!(stored.len(), 1);
310→        } else {
311→            panic!("Expected MultiSelect variant");
312→        }
313→    }
314→
315→    #[test]
316→    fn is_yes_no_returns_true_for_yes_no_options() {
317→        let options = vec![
318→            PromptOption {
319→                label: "Yes (y)".to_string(),
320→                value: "yes".to_string(),
321→            },
322→            PromptOption {
323→                label: "No (n)".to_string(),
324→                value: "no".to_string(),
325→            },
326→        ];
327→        assert!(is_yes_no(&options));
328→    }
329→
330→    #[test]
331→    fn is_yes_no_returns_true_regardless_of_order() {
332→        let options = vec![
333→            PromptOption {
334→                label: "No (n)".to_string(),
335→                value: "no".to_string(),
336→            },
337→            PromptOption {
338→                label: "Yes (y)".to_string(),
339→                value: "yes".to_string(),
340→            },
341→        ];
342→        assert!(is_yes_no(&options));
343→    }
344→
345→    #[test]
346→    fn is_yes_no_returns_false_for_other_options() {
347→        let options = vec![
348→            PromptOption {
349→                label: "Option A".to_string(),
350→                value: "a".to_string(),
351→            },
352→            PromptOption {
353→                label: "Option B".to_string(),
354→                value: "b".to_string(),
355→            },
356→        ];
357→        assert!(!is_yes_no(&options));
358→    }
359→
360→    #[test]
361→    fn is_yes_no_returns_false_for_more_than_two() {
362→        let options = vec![
363→            PromptOption {
364→                label: "Yes".to_string(),
365→                value: "yes".to_string(),
366→            },
367→            PromptOption {
368→                label: "No".to_string(),
369→                value: "no".to_string(),
370→            },
371→            PromptOption {
372→                label: "Maybe".to_string(),
373→                value: "maybe".to_string(),
374→            },
375→        ];
376→        assert!(!is_yes_no(&options));
377→    }
378→
379→    #[test]
380→    fn select_theme_creates_without_panic() {
381→        let theme = select_theme();
382→        // Verify the theme object can be used (smoke test)
383→        drop(theme);
384→    }
385→}
